  path: 'm/:module',
  canActivate: [authGuard, moduleGuard],
  loadComponent: () => import('./modules/module.component').then(m => m.ModuleComponent)
}, {
  path: 'new/:docType',
  canActivate: [authGuard, createGuard],
  loadComponent: () => import('./documents/doc-form.component').then(m => m.DocFormComponent)
}, {
  path: 'approvals',
  canActivate: [authGuard, permGuard('tasks.act')],
  loadComponent: () => import('./tasks/tasks.component').then(m => m.TasksComponent)
}, {
  path: 'documents',
  canActivate: [authGuard],
  loadComponent: () => import('./requests/requests.component').then(m => m.RequestsComponent)
}, {
  path: 'documents/:id',
  canActivate: [authGuard],
  loadComponent: () => import('./requests/request-detail.component').then(m => m.RequestDetailComponent)
}, {
  path: 'services',
  canActivate: [authGuard],
  loadComponent: () => import('./submit/submit.component').then(m => m.SubmitComponent)
}, {
  path: 'reports',
  canActivate: [authGuard, permGuard('reports.view')],
  loadComponent: () => import('./reports/reports.component').then(m => m.ReportsComponent)
}, {
  path: 'assistant',
  canActivate: [authGuard, permGuard('assistant.use')],
  loadComponent: () => import('./assistant/assistant-page.component').then(m => m.AssistantPageComponent)
